#include <vector>
#include <iostream>

int main() {
    // Create a vector to store integers
    std::vector<int> numbers;  // Default constructor, starts empty
    numbers.reserve(10);  // Reserve space for efficiency, avoiding reallocations

    // Add elements dynamically
    numbers.push_back(42);  // Appends 42
    numbers.push_back(17);  // Appends 17

    // Access and iterate with bounds safety
    for (const auto& num : numbers) {
        std::cout << num << " ";  // Output: 42 17
    }

    // Check size and access with bounds checking
    if (!numbers.empty()) {
        std::cout << "\nFirst element: " << numbers.at(0) << std::endl;  // Safe access
    }

    return 0;
}
